mapper.select:
select t1.REMINDERSTAFFID, t1.CREATEDTIME, COALESCE(t2.REMINDERCONTENT, t5.REMINDERCONTENT) as reminderContent, COALESCE(t2.CREATEDTIME, t5.CREATEDTIME) as reminderTime from TBL_SYSTEM_REF_REMINDER_ACCESS_V t1 left join TBL_SYSTEM_REF_REMINDER_V t2 on t2.ID = t1.REMINDERID left join TBL_SYSTEM_REF_REMINDER t5 on t5.ID = t1.REMINDERID left join TBL_STAFF t4 on t4.STAFFID = t1.REMINDERSTAFFID where t1.REMINDERSTAFFID = #{param.creator}
and t4.REALNAME like concat('%',concat(#{param.reminderStaffName},'%'))
order by t1.CREATEDTIME desc
